SELECT c.id, u.id,
       CASE WHEN random() < 0.5 THEN 'vouch' ELSE 'fit' END,
       'Happy to help — I work near this space.',
       NOW() - (random()*20 || ' days')::interval
  FROM challenges c
  JOIN LATERAL (SELECT id FROM users WHERE id <> c.user_id AND is_seed_beta ORDER BY random() LIMIT 3) u ON TRUE;

